//     }
// }

// /*
// =========================================================
// CONTRACT B
// MIDDLE CONTRACT
// =========================================================
// */

// contract ContractBVul {
//     /*
//         STORE CONTRACT C
//     */
//     ContractCVul public contractC;

//     /*
//         TRACK EXECUTION
//     */
//     uint256 public middleCounter;

//     /*
//         CONSTRUCTOR
