//     function callFinalStep() external{
//         /*
//             Local state update.
//         */
//         middleCounter++;

//         /*
//             EXTERNAL CALL:
//             Contract B -> Contract C
//         */
//         contractC.finalStep();
//     }

//     /*
//     =====================================================
//     CALL FAILING FUNCTION
//     =====================================================
